  sup_s: (a, b, f, down, v, r) => `From ${a} to ${b} you go ${f === "100" ? (down ? "one step down" : "one step up") : (down ? "two steps down" : "two steps up")} the staircase, and for area each step is × 100: ${down ? "multiply by" : "divide by"} ${f}. ${v} ${down ? "×" : "÷"} ${f} = <b>${r} ${b}</b>.`,
  dias: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
  diasL: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
  lin_q: d => `The graph shows the high temperature (°C) for each day of one week. What was the temperature on <b>${d}</b>?`,
  lin_s: (d, v) => `Find the point for ${d} and read its height on the axis: <b>${v} °C</b>.`,
  lind_q: (a, b) => `The graph shows the high temperature (°C) for one week. By how many degrees did the temperature change from ${a} to ${b}?`,
  lind_s: (a, b) => `${a} °C and ${b} °C: the difference is <b>${Math.abs(b - a)} °C</b> (it went ${b > a ? "up" : "down"}).`,
  linm_q: "The graph shows the high temperature (°C) for one week. Which day was the warmest?",
  linm_s: (d, v) => `The highest point is <b>${d}</b>, with ${v} °C.`,
  lin_par: (a, b) => `${a} to ${b}`,
  linsub_q: "The graph shows the high temperature (°C) for one week. Between which two days in a row did the temperature rise the most?",
  linsub_s: (subidas, par, a, b, d) => `Look at where the line goes up and by how much: ${subidas}. The biggest rise is ${par}: from ${a} °C to ${b} °C, up <b>${d} °C</b>.`,
  vol_q: "How many small cubes make up this prism? (Each small cube is 1 cm³.)",
  vol_s: (a, b, c, r) => `Volume = length × width × height = ${a} × ${b} × ${c} = <b>${r} cm³</b>.`,
  vol2_s: (a, b, down, v, r) => `For volume, each step is × 1,000 (1 m = 10 dm, and 1 m³ = 10 × 10 × 10 dm³). From ${a} to ${b}, ${down ? "multiply by" : "divide by"} 1,000: <b>${r} ${b}</b>.`,
  cv_q: (v, a, b) => `How many <b>${b === "L" ? "liters" : b}</b> fit in <b>${v} ${a}</b>?`,
  cv_s0: v => `1 dm³ = 1 liter (1 L), so ${v} dm³ = <b>${v} L</b>.`,
  cv_s1: (v, r) => `1 m³ = 1,000 dm³ = 1,000 liters, so ${v} m³ = <b>${r} L</b>.`,
  cv2_q: (a, b, c) => `A fish tank is ${a} dm long, ${b} dm wide, and ${c} dm high. How many liters of water does it hold?`,
  cv2_s: (a, b, c, r) => `V = ${a} × ${b} × ${c} = ${r} dm³, and 1 dm³ = 1 L: it holds <b>${r} liters</b>.`,
  ag_q: (v, a, b) => `Convert <b>${v} ${a}</b> to <b>${b}</b>.`,
  ag_s0: (v, r) => `1 hectare (ha) = 1 hm² = 10,000 m²: ${v} ha = <b>${r} m²</b>.`,
  ag_s1: (v, r) => `1 are (a) = 1 dam² = 100 m²: ${v} a = <b>${r} m²</b>.`,
  ag_s2: (v, r) => `1 ha = 10,000 m²: ${v} m² = <b>${r} ha</b>.`,
  trap_q: "Find the area of this trapezoid, in cm².",
  trap_s: (B, b, h, r) => `A = (B + b) × h ÷ 2 = (${B} + ${b}) × ${h} ÷ 2 = <b>${window.WA.H.dec(r)} cm²</b>.`,
  eu_w: ["faces", "vertices", "edges"],
  eu_poli: ["a cube", "a tetrahedron", "an octahedron", "a pentagonal prism", "a pentagonal pyramid", "a dodecahedron", "an icosahedron", "a hexagonal prism"],
  eu_q: (n, known, miss) => `A polyhedron has ${lst5(known)}. How many ${miss} does it have? Use Euler's formula.`,
  eu_s: (c, v, a, k, n) => `Euler's formula: F + V = E + 2 (faces + vertices = edges + 2). ` + [
    `Substitute the values: F + ${v} = ${a} + 2, that is, F + ${v} = ${a + 2}, so F = ${a + 2} − ${v} = <b>${c}</b> faces.`,
    `Substitute the values: ${c} + V = ${a} + 2, that is, ${c} + V = ${a + 2}, so V = ${a + 2} − ${c} = <b>${v}</b> vertices.`,
    `Substitute the values: ${c} + ${v} = E + 2, that is, ${c + v} = E + 2, so E = ${c + v} − 2 = <b>${a}</b> edges.`][k] + ` (For example, ${n} has these numbers: check by counting.)`,
  // ── Grade 5: elementary versions (× and ÷, "divided by", steps from the lessons) ──
