  hint_pct: "Write only the number, without the % sign",
  ld_first: (c, d, q, p, r) => `Start with ${c}: ${d} goes into it ${q === 1 ? "once" : `${q} times`} (${d} × ${q} = ${p}), with ${r} left over.`,
  ld_step: (dig, cur, d, q, p, r) => `Bring down the ${dig}: ${cur}. It goes in ${q === 1 ? "once" : `${q} times`} (${d} × ${q} = ${p}), with ${r} left over.`,
