  div_s: (a, d, q, r, p) => `Quotient <b>${q}</b>, remainder <b>${r}</b>. Check: ${d} × ${q} + ${r} = ${p} + ${r} = ${a} ✔ (and the remainder is less than the divisor).`,
  dvd_q: (d, q, r) => `In a division problem, the divisor is <b>${d}</b>, the quotient is <b>${q}</b>, and the remainder is <b>${r}</b>. What is the dividend?`,
  dvd_s: (d, q, r, p, D) => `Dividend = divisor × quotient + remainder = ${d} × ${q} + ${r} = ${p} + ${r} = <b>${D}</b>.`,
  pv_q: p => `Find <b>${p}</b>.`,
  pv_s: (p, prod, st, r) => st.length > 1 ? `${p} = ${prod}. Multiply step by step: ${st.join("; ")}. ${p} = <b>${r}</b>.` : `${p} = ${prod} = <b>${r}</b>.`,
  pp_q: (p, what) => `In the power <b>${p}</b>, what is ${what === "b" ? "the base" : "the exponent"}?`,
