  rz_s10: (n, m, a, r) => `${n} ends in two zeros: drop them and think of √${m} = ${a}. Try ${r}: ${r} × ${r} = ${n} ✔. The square root is <b>${r}</b>.`,
  rze_q: r => `<b>${r}</b> is between two consecutive whole numbers. Which ones?`,
