  mul_s: (a, b, q, r) => r ? `Divide: ${a} ÷ ${b} = ${q} with ${r} left over. Since the remainder is not 0, ${a} is <b>not</b> a multiple of ${b}.` : `Divide: ${a} ÷ ${b} = ${q} and the remainder is 0 (${b} × ${q} = ${a}). ${a} <b>is</b> a multiple of ${b}.`,
  dvs_q: n => `Write all the factors of <b>${n}</b>.`,
