  dm_s: (ia, ib, p, a, ka, b, kb, k, full, trim, lead) => `Multiply without the decimal points: ${ia} × ${ib} = ${p}. ${ka ? `${a} has ${ka} decimal place${ka === 1 ? "" : "s"} and ${b} has ${kb}: ${k} in all` : `${b} has ${kb} decimal place${kb === 1 ? "" : "s"}`}. Count ${k} ${k === 1 ? "place" : "places"} from the right${lead ? " (there are not enough digits, so write zeros in front)" : ""}: ${full === trim ? `<b>${full}</b>` : `${full} = <b>${trim}</b> (you can drop the zeros at the end)`}.`,
