  pcd_q: (p, c) => `Find <b>${p}%</b> of <b>${c}</b>.`,
  pcd_s: (p, c, cn, r) => {
    const t = cn / 10, q4 = cn / 4;
    const way = p === 10 ? `10% means dividing by 10: ${c} ÷ 10 = <b>${r}</b>.`
      : p === 50 ? `50% is half: ${c} ÷ 2 = <b>${r}</b>.`
      : p === 25 ? `25% is one-fourth: ${c} ÷ 4 = <b>${r}</b>.`
      : p === 75 ? `25% is one-fourth: ${c} ÷ 4 = ${q4}. 75% is three times that: 3 × ${q4} = <b>${r}</b>.`
      : p === 5 ? `10% of ${c} is ${c} ÷ 10 = ${t}. 5% is half of that: ${t} ÷ 2 = <b>${r}</b>.`
      : `10% of ${c} is ${c} ÷ 10 = ${t}. ${p}% is ${p / 10} times 10%: ${p / 10} × ${t} = <b>${r}</b>.`;
    return `${way} (Using the rule: ${p} × ${c} ÷ 100 = ${r}.)`;
  },
  pcd_obj: ["A video game", "A T-shirt", "A pair of sneakers", "A ball", "A backpack"],
  pcd_desc_q: (o, c, p) => `${o} costs $${c} and is ${p}% off. How much do you pay, in dollars?`,
  pcd_desc_s: (p, c, d, r) => `First, the discount: ${p === 10 ? `10% is ${c} ÷ 10 = $${d}` : p === 50 ? `50% is half, ${c} ÷ 2 = $${d}` : p === 25 ? `25% is one-fourth, ${c} ÷ 4 = $${d}` : `10% is ${c} ÷ 10 = $${c / 10}, and ${p}% is ${p / 10} × ${c / 10} = $${d}`}. Then subtract it: ${c} − ${d} = <b>$${r}</b>.`,
  pcq_q: (a, b) => `What percent of ${b} is ${a}?`,
  pcq_q2: (a, b) => `On a test with ${b} questions, you get ${a} right. What percent did you get right?`,
  pcq_q3: (a, b) => `In a school with ${b} students, ${a} take the bus to school. What percent of the students is that?`,
  pcq_s_amp: (b, k, f, f2, p) => `Write the fraction ${f} and find an equivalent fraction with denominator 100: ${b} × ${k} = 100, so multiply the top and bottom by ${k}. ${f} = ${f2}: <b>${p}%</b>.`,
  pcq_s_simp: (k, f, f2, p) => `Write the fraction ${f} and simplify it, dividing the top and bottom by ${k}, so that the denominator is 100: ${f} = ${f2}: <b>${p}%</b>.`,
  // eur: amounts of money (u = "$": the sign goes in front)
