  me_comp: [["kg", "g", 1000], ["m", "cm", 100], ["L", "mL", 1000], ["km", "m", 1000], ["m", "dm", 10]],
  me_comp_q: (a, u1, b, u2, to) => `Convert <b>${a} ${u1} ${b} ${u2}</b> to <b>${to}</b>.`,
  me_comp_s1: (a, u1, b, u2, f, x, r) => `Convert each part to ${u2}: ${a} ${u1} = ${a} × ${f} = ${x} ${u2}. Add the ${b} ${u2}: ${x} + ${b} = <b>${r} ${u2}</b>.`,
  me_comp_s2: (a, u1, b, u2, f, x, r) => `Convert the ${b} ${u2} to ${u1}: ${b} ÷ ${f} = ${x} ${u1}. Add the ${a} ${u1}: ${a} + ${x} = <b>${r} ${u1}</b>.`,
  me_s: (a, b, k, down, chain, f, v, r) => `From ${a} to ${b} you go ${steps5(k)} ${down ? "down" : "up"} (${chain}): ${down ? "multiply by" : "divide by"} ${f}. The decimal point moves ${k} ${k === 1 ? "place" : "places"} to the ${down ? "right" : "left"}: ${v} ${a} = <b>${r} ${b}</b>.`,
  ci_obj: [["A bicycle wheel", 40, 70], ["A round fountain", 100, 300], ["A round table", 80, 150], ["A plate", 18, 30], ["A hula hoop", 50, 90], ["A cake", 16, 32]],
