  ar_rect_s: (b, h, r) => `Area of a rectangle = base × height = ${b} × ${h} = <b>${r} cm²</b>.`,
  ar_cuad_s: (l, r) => `Area of a square = side × side = ${l} × ${l} = <b>${r} cm²</b>.`,
  ar_tri_s: (b, h, p, r) => `Area of a triangle = base × height ÷ 2 = ${b} × ${h} ÷ 2 = ${p} ÷ 2 = <b>${r} cm²</b>.`,
