  ar_inv_q: (A, b) => `A rectangle has an area of ${A} cm² and a base of ${b} cm. What is its height? (In cm.)`,
  ar_inv_s: (A, b, h) => `Base × height = ${A}, so the height is ${A} ÷ ${b} = <b>${h} cm</b>. Check: ${b} × ${h} = ${A} ✔`,
  ar_l_q: "Find the area of this L-shaped room (in m²).",
  ar_l_s: (W, Hb, Ab, Hh, hn, Wt, At, A) => `Split the room into two rectangles with a line. Bottom: ${W} × ${Hb} = ${Ab} m². Top: the room is ${Hh} m tall and the bottom rectangle is ${Hb} m, so the top one is ${Hh} − ${Hb} = ${hn} m: ${Wt} × ${hn} = ${At} m². Total: ${Ab} + ${At} = <b>${A} m²</b>.`,
  ar_fach_q: (b, a, t) => `The front of a little house is a rectangle ${b} m wide and ${a} m high, with a triangular roof that has a base of ${b} m and a height of ${t} m. What is the area of the whole front? (In m².)`,
  ar_fach_s: (b, a, Ar, t, p, At, A) => `Wall (rectangle): ${b} × ${a} = ${Ar} m². Roof (triangle): ${b} × ${t} ÷ 2 = ${p} ÷ 2 = ${At} m². Whole front: ${Ar} + ${At} = <b>${A} m²</b>.`,
  se_dep: ["basketball", "swimming", "tennis", "cycling", "track and field", "skating", "soccer"],
