  ml_cmp_s: (a, b, res, trampa) => `Give both numbers the same number of decimal places by writing zeros: ${a} and ${b}. Compare from left to right: <b>${res}</b>.${trampa ? " (Having more digits does not make a decimal greater!)" : ""}`,
