  dd_fin: (n, q, D) => `Quotient: <b>${q}</b>. Check: ${n} × ${q} = ${D} ✔`,
  dps_cosas: [["notebooks", "a pencil case"], ["pens", "a folder"], ["ice-cream cones", "a bottle of water"], ["packs of stickers", "an album"], ["tickets", "a bag of popcorn"]],
